// Constructs a Compressed Sparse Column (CSC) representation from the
// paralog.tsv output generated by the clustering pipeline
// The resulting matrix is written as three binary files
//   indptr  : column pointer array (u64)
//   indices : row indices of non-zero entries (u32 mag_id)
//   data    : copy number of each non-zero entry (u16; the run aborts if a value exceeds 65535)
// The binary format is chosen to allow direct memory mapping
// (e.g. via numpy.memmap) without requiring an additional conversion step
// paralog.tsv is written cluster by cluster, so all rows of a family are contiguous and family_ids increase:
// the columns can be written in order in a single streaming pass, no sorting of the whole file is needed (unlike CSR)
// Only rows of a single family are buffered in memory at a time
// Memory usage scales with the largest family not the total number of rows in the input file

// Imports
use std::env;
use std::fs::File;
use std::io::{self, BufRead, BufReader, BufWriter, Write};

// Buffer sizes for reading and writing operations, in MiB.
// Can be overridden via the environment variables MAGRIX_READ_BUF_MB / MAGRIX_WRITE_BUF_MB.
// 8 MiB each: no measurable speed difference between 1 and 256 MiB in the buffer sweep (results/).
const DEFAULT_READ_BUF_MB: usize = 8;
const DEFAULT_WRITE_BUF_MB: usize = 8;

// Buffer size in bytes: the environment variable `var` (in MiB) if set, else the default.
fn buffer_size(var: &str, default_mb: usize) -> usize {
    let mb = match env::var(var) {
        Ok(v) => v.parse::<usize>().ok().filter(|&n| n > 0)
            .unwrap_or_else(|| panic!("{} must be a positive integer (MiB), got {:?}", var, v)),
        Err(_) => default_mb,
    };
    mb * 1024 * 1024
}

// Copy numbers are stored as u16. Abort instead of silently truncating if one doesn't fit.
fn to_u16(value: u32) -> u16 {
    u16::try_from(value).unwrap_or_else(|_| panic!("copy number {} exceeds u16 range (max 65535)", value))
}

fn main() -> io::Result<()> {

    // Parse command line arguments
    // 0: program name, 1: paralog.tsv, 2: num_families, 3: out_prefix
    let args: Vec<String> = env::args().collect();
    if args.len() != 4 {
        eprintln!("Usage: build_csc <paralog.tsv> <num_families> <out_prefix>");
        std::process::exit(1);
    }
    let tsv_path = &args[1];
    // Needed to preallocate the indptr array including empty families
    let num_families: u32 = args[2].parse().expect("num_families must be an integer");
    let out_prefix = &args[3];

    let read_buf = buffer_size("MAGRIX_READ_BUF_MB", DEFAULT_READ_BUF_MB);
    let write_buf = buffer_size("MAGRIX_WRITE_BUF_MB", DEFAULT_WRITE_BUF_MB);
    eprintln!("Buffers: read={} MiB write={} MiB", read_buf >> 20, write_buf >> 20);

    let infile = File::open(tsv_path)?;
    // stream the input file line by line, using a buffered reader for efficiency
    let reader = BufReader::with_capacity(read_buf, infile);

    // Output files for the CSC representation
    // indptr: column start offsets
    // indices: row indices (mag_id)
    // data: copy numbers (paralog_count)
    let mut indptr_w = BufWriter::with_capacity(write_buf, File::create(format!("{}.csc.indptr", out_prefix))?);
    let mut indices_w = BufWriter::with_capacity(write_buf, File::create(format!("{}.csc.indices", out_prefix))?);
    let mut data_w = BufWriter::with_capacity(write_buf, File::create(format!("{}.csc.data", out_prefix))?);
   
    // Rows belonging to the currently processed family
    // Stores (mag_id, value) pairs until the family is complete
    let mut buffer: Vec<(u32, u16)> = Vec::new(); // (mag_id, value)
    let mut current_family: Option<u32> = None; // the family_id of the rows currently in the buffer
    let mut next_indptr_family: u32 = 0; // Next family whose indptr entry needs to be written, Starts at 0
    let mut cum_offset: u64 = 0; // total entries written to indices/data so far,used to fill indptr
    let mut rows_read: u64 = 0;
    let mut max_value: u32 = 0; // diagnostic only: largest copy number, printed in the summary

    // Write one family's rows to csc storage
    // Sorts the buffer by mag_id, writes to indices/data, updates cum_offset, and clears the buffer
    let flush_family = |buffer: &mut Vec<(u32, u16)>,
                         indices_w: &mut BufWriter<File>,
                         data_w: &mut BufWriter<File>,
                         cum_offset: &mut u64|
     -> io::Result<()> {
        // Sort the buffer by mag_id to ensure the CSC format's requirement that row indices are sorted within each column
        // (stage 1 writes the MAGs of a cluster in arbitrary HashMap order)
        buffer.sort_unstable_by_key(|&(mag_id, _)| mag_id);
        for &(mag_id, value) in buffer.iter() {
            indices_w.write_all(&mag_id.to_le_bytes())?;
            data_w.write_all(&value.to_le_bytes())?;
        }
        // Advance the cumulative offset by the number of entries just written, and clear the buffer for the next family
        *cum_offset += buffer.len() as u64;
        buffer.clear();
        Ok(())
    };

    for line in reader.lines() {
        let line = line?;
        // Skip empty lines and the header line
        if line.is_empty() || line.starts_with("representative_gene") {
            continue;
        }
        let mut parts = line.split('\t');
        // representative_gene is ignored, family_id uniquely identifies the column
        let _rep = parts.next().unwrap();
        let family_id: u32 = parts.next().unwrap().parse().expect("bad family_id");
        let mag_id: u32 = parts.next().unwrap().parse().expect("bad mag_id");
        let value: u32 = parts.next().unwrap().parse().expect("bad value");
        rows_read += 1;
        // Track the maximum value seen in the data for diagnostic purposes
        if value > max_value {
            max_value = value;
        }

        // If the current row belongs to a new family, flush the previous family's rows to disk and update the indptr array
        if current_family != Some(family_id) {
            if let Some(prev) = current_family {
                // CSC requires increasing family_id order
                assert!(family_id > prev, "input not sorted by family_id: {} after {}", family_id, prev);
                flush_family(&mut buffer, &mut indices_w, &mut data_w, &mut cum_offset)?;
            }

            // Write indptr entries up to the new family_id 
            // Every family whose rows start at the current cumulative offset (including skipped families) gets an indptr entry
            // Automatically handles the case where there are empty families (no rows) between the last processed family and the current one
            while next_indptr_family <= family_id {
                indptr_w.write_all(&cum_offset.to_le_bytes())?;
                next_indptr_family += 1;
            }
            current_family = Some(family_id);
        }
        // Accumulate rows until the family is complete
        buffer.push((mag_id, to_u16(value)));
    }

    // Flush the last family (the loop above only flushes a family when the next one starts)
    flush_family(&mut buffer, &mut indices_w, &mut data_w, &mut cum_offset)?;
    // Write the final indptr entry for the last family, and fill in any empty families after it
    while next_indptr_family <= num_families {
        indptr_w.write_all(&cum_offset.to_le_bytes())?;
        next_indptr_family += 1;
    }

    indptr_w.flush()?;
    indices_w.flush()?;
    data_w.flush()?;

    eprintln!(
        "CSC done. rows_read={} nnz={} num_families={} max_value={}",
        rows_read, cum_offset, num_families, max_value
    );
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn to_u16_keeps_values_in_range() {
        assert_eq!(to_u16(280), 280);
        assert_eq!(to_u16(65535), 65535);
    }

    #[test]
    #[should_panic(expected = "exceeds u16 range")]
    fn to_u16_panics_instead_of_truncating() {
        to_u16(65536);
    }
}
